with matched_keys as (select manager_id, job_title from employees intersect all select manager_id, job_title from employees where salary <= 67000), verified as (select s.* from employees s inner join matched_keys k on s.manager_id = k.manager_id and s.job_title = k.job_title) select email, dept_id, manager_id, salary, hire_date, is_remote, level, case when level rlike '^(L3|L4)$' then 'OTHER_ZONE' when level rlike '^(L1|L2)$' then 'EXTENDED' else 'GROUP_A' end as level_zone from verified order by manager_id desc nulls last;
